window.AUTH=window.AUTH||{};window.AUTH["20-979"]={"d":"20-979","id":"2021/20-979","n":"Patel v. Garland","briefs":[{"k":"petitioner","label":"Brief of petitioners Pankajkumar S. Patel, et al.","date":"2021-08-31","url":"https://www.supremecourt.gov/DocketPDF/20/20-979/190044/20210831173107019_20-979%20ts.pdf","side":"pet","n":57},{"k":"respondent","label":"Brief of respondent Merrick B. Garland, Attorney General in support","date":"2021-08-31","url":"https://www.supremecourt.gov/DocketPDF/20/20-979/190049/20210831180548915_20-979tsUnitedStates.pdf","side":"res","n":98},{"k":"reply","label":"Reply of petitioners Pankajkumar S. Patel, et al.","date":"2021-11-18","url":"https://www.supremecourt.gov/DocketPDF/20/20-979/200544/20211118155151059_20-979%20rb.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us1r31_5367.pdf","tr":true,"items":[{"t":"case","label":"Azar v. Allina Health Services","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"does not lightly assume that Congress silently attaches different meanings to the same term in the same … statute[].","cite":"139 S. Ct. 1804, 1812"}]},{"t":"case","label":"Babb v. Wilkie","cite":"140 S. Ct. 1168","y":2020,"id":"2019/18-882","sc":1,"by":{"0":"37, 38"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"by":{"0":"5","1":"3"}},{"t":"case","label":"Billeke-Tolosa v. Ashcroft","cite":"385 F.3d 708","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/385/708/","by":{"0":"10"}},{"t":"case","label":"Block v. Community Nutrition Institute","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"by":{"0":"43","2":"20"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"drawn from the statutory scheme as a whole.","cite":"467 U. S. 340, 349"}]},{"t":"case","label":"Dada v. Mukasey","cite":"554 U.S. 1","y":2008,"id":"2007/06-1181","sc":1,"by":{"0":"25"}},{"t":"case","label":"Department of Homeland Security v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"by":{"0":"29, 30"}},{"t":"case","label":"Diaz-Resendez v. INS","cite":"960 F.2d 493","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/960/493/","by":{"0":"9","2":"11"}},{"t":"case","label":"Drobny v. INS","cite":"947 F.2d 241","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/947/241/","by":{"0":"9","2":"11"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"0":"24"}},{"t":"case","label":"Foti v. INS","cite":"375 U.S. 217","y":1963,"id":"1963/28","sc":1,"by":{"0":"6, 9","2":"15"},"q":[{"src":"argument","who":"Mr. Fleming","text":"\"Regarding the granting of relief,\" we believe, calls in the traditional distinction which this Court has noted several times, going back to Foti versus INS and St."}]},{"t":"case","label":"Fry v. Napoleon Community Schools","cite":"137 S. Ct. 743","y":2017,"id":"2016/15-497","sc":1,"by":{"0":"23"}},{"t":"case","label":"Gobeille v. Liberty Mutual Insurance Co.","cite":"577 U.S. 312","y":2016,"id":"2015/14-181","sc":1,"by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"‘uncritical literalism’ [would] lead[] to results that ‘no sensible person could have intended.’","cite":"577 U.S. 312, 319"}]},{"t":"case","label":"Gonzales-Oropeza v. U.S. Attorney General","cite":"321 F.3d 1331","y":2003,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/321/1331/","by":{"0":"42","1":"31"}},{"t":"case","label":"Gonzales-Torres v. INS","cite":"213 F.3d 899","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/213/899/","by":{"0":"10"}},{"t":"case","label":"Page(s) Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"by":{"0":"32, 40, 43","1":"32, 33, 34, 37, 38","2":"18"},"q":[{"src":"brief","b":0,"text":"‘executive determinations generally are subject to judicial review.’","cite":"140 S. Ct. at 1069"},{"src":"brief","b":0,"text":"[s]ome, regardless of quantity or number,","cite":"140 S. Ct. at 1173"},{"src":"brief","b":1,"text":"normally assume[s] that Congress is ‘aware of relevant judicial precedent’ when it enacts a new statute.","cite":"140 S. Ct. at 1072"},{"src":"brief","b":1,"text":"indicates that Congress was well aware of the state of the law in the courts of appeals in light of St. Cyr.","cite":"140 S. Ct. at 1072"}]},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"begins … with a careful examination of the statutory text.","cite":"137 S. Ct. 1718, 1721"}]},{"t":"case","label":"Hall Street Associates, LLC v. Mattel, Inc.","cite":"552 U.S. 576","y":2008,"id":"2007/06-989","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"set[ting] out a series of specific items ending with a general term,","cite":"552 U.S. 576, 586"}]},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"0":"29, 32"},"q":[{"src":"brief","b":0,"text":"longstanding principle of construing any lingering ambiguities in deportation statutes","cite":"480 U.S. 421, 449"},{"src":"brief","b":0,"text":"[d]eportation is always a harsh measure.","cite":"480 U.S. at 449"}]},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"by":{"0":"8","2":"7"},"q":[{"src":"brief","b":0,"text":"review of a final order of removal ‘includes all matters on which the validity of the final order is contingent’","cite":"462 U.S. 919, 938"},{"src":"argument","who":"Mr. Fleming","text":"And as this Court said in Chadha, the final order of removal subsumes everything that goes before. The question for purposes of interpreting the jurisdictional bar is what Congress meant by the phrase \"any judgment regarding the granting of relief.\""},{"src":"argument","who":"Mr. Fleming","text":"This Court in INS versus Chadha said the term \"final orders\" includes all matters on which the validity of the final order is contingent. The statute itself talks about review of the final order."}]},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"0":"passim","1":"passim","2":"14"},"q":[{"src":"brief","b":0,"text":"actual granting of relief [is] ‘not a matter of right under any circumstances, but rather is in all cases a matter of grace.’","cite":"533 U.S. 289, 308"},{"src":"brief","b":0,"text":"distinction between eligibility for discretionary relief, on the one hand, and the favorable exercise of discretion, on the other hand.","cite":"533 U.S. at 307"},{"src":"brief","b":1,"text":"courts generally did not review factual determinations made by the Executive.","cite":"533 U.S. at 306"},{"src":"brief","b":1,"text":"preserve[s] review of ‘questions of law.’","cite":"533 U.S. at 307"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"`not a matter of right under any circumstances, but rather is in all cases a matter of grace.'","cite":"533 U. S., at 308"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"the actual granting of relief . . . is in all cases a matter of grace.","cite":"533 U. S. 289, 308"}]},{"t":"case","label":"iTech U.S., Inc. v. Renaud","cite":"5 F.4th 59","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/5/59/","by":{"0":"25, 38"}},{"t":"case","label":"Jay v. Boyd","cite":"351 U.S. 345","y":1956,"id":"1955/503","sc":1,"by":{"0":"6, 20","1":"28"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"0":"19, 38"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"by":{"0":"46"}},{"t":"case","label":"Knauer v. United States","cite":"328 U.S. 654","y":1946,"id":"scdb/1945-027","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"may result in the loss ‘of all that makes life worth living.’","cite":"328 U.S. 654, 659"}]},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"by":{"0":"passim","1":"passim","2":"1, 5, 6, 13, 14, 15"},"q":[{"src":"brief","b":0,"text":"free hand to shelter its own decisions from appellate court review.","cite":"558 U.S. at 252"},{"src":"brief","b":0,"text":"consider[ed] in connection with … the whole statute.","cite":"558 U.S. at 244"},{"src":"brief","b":1,"text":"states that a noncitizen may not bring a factual challenge to orders denying discretionary relief, including cancellation of removal, voluntary departure, adjustment of status, certain inadmissibility waivers, and other determinations ‘made discretionary by statute,’","cite":"558 U.S. at 248"},{"src":"brief","b":1,"text":"bars court review of discretionary decisions.","cite":"558 U.S. at 247"},{"src":"brief","b":2,"text":"any books by famous crime novelists.","cite":"558 U.S. at 247"},{"src":"brief","b":2,"text":"[e]ach of the statutory provisions referenced in clause (i) … contains language indicating that the decision is … discretion[ary].","cite":"558 U.S. at 246"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"The proxim- Page Proof Pending Publication ity of clauses (i) and (ii), and the words linking them—`any other decision'—suggests that Congress had in mind decisions of the same genre, i. e., those made discretionary by legislation.","cite":"558 U. S. 233, 246–247"},{"src":"argument","who":"Mr. Fleming","text":"That understanding is consistent with the statutory text, context, and history, and it's also consistent with this Court's explanation in Kucana that the (B)(i) bar is limited to decisions made discretionary by legislation."},{"src":"argument","who":"Mr. Fleming","text":"Most importantly, it's the reasoning that this Court employed in Kucana because (B)(ii) uses \"any other decision or action,\" which links (B)(i) and (B)(ii) together in a way that this Court said shows that both sections were directed to decisions made discretionary by statute."},{"src":"argument","who":"Mr. Fleming","text":"I mean, the -- the -- this Court applied the presumption of reviewability in Kucana, just last year in Guerrero-Lasprilla. Those were interpreting these very same provisions, and there was no suggestion that the presumption had any less force in those cases or that it should have any less force here because the presumption implements the important separation-of-powers consideration that we don't assume that Congress is allowing the Executive Branch to have the last word on whether it's complying with congressional mandates --"}]},{"t":"case","label":"Lee v. United States","cite":"137 S. Ct. 1958","y":2017,"id":"2016/16-327","sc":1,"by":{"0":"32"}},{"t":"case","label":"Lee v. USCIS","cite":"592 F.3d 612","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/592/612/","by":{"0":"41"}},{"t":"case","label":"Mamigonian v. Biggs","cite":"710 F.3d 936","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/710/936/","by":{"0":"11, 41, 42","1":"35"}},{"t":"case","label":"McNary v. Haitian Refugee Center, Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"most unlikely that Congress intended to foreclose all forms of meaningful judicial review","cite":"498 U.S. 479, 496"},{"src":"argument","who":"Ms. Meehan","text":"The best example of that distinction is in McNary, which is helpfully an immigration case where the presumption of review was at issue. In McNary, the Court reviewed what it called a generic question of statutory interpretation about visas for these special agricultural workers."}]},{"t":"case","label":"Mendez v. Holder","cite":"566 F.3d 316","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/566/316/","by":{"0":"23, 34"},"q":[{"src":"brief","b":0,"text":"whether an alien has demonstrated that sufficient hardship would result from his or her removal is … not a discretionary decision","cite":"566 F.3d at 322"}]},{"t":"case","label":"Mendez-Moranchel v. Ashcroft","cite":"338 F.3d 176","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/338/176/","by":{"0":"10, 41","1":"31"},"q":[{"src":"brief","b":0,"text":"inferred from contemporaneous judicial construction … and the congressional acquiescence in it,","cite":"338 F.3d 176, 178"}]},{"t":"case","label":"Mireles-Valdez v. Ashcroft","cite":"349 F.3d 213","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/349/213/","by":{"0":"42"}},{"t":"case","label":"Montero-Martinez v. Ashcroft","cite":"277 F.3d 1137","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/277/1137/","by":{"0":"10, 21, 22, 27, 42","1":"24, 31, 32"},"q":[{"src":"brief","b":1,"text":"constitutes a fairly customary or traditional way of ensuring that all the relevant provisions are covered.","cite":"277 F.3d 1137, 1143 n.7"}]},{"t":"case","label":"Mortera-Cruz v. Gonzales","cite":"409 F.3d 246","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/409/246/","by":{"0":"45"}},{"t":"case","label":"Mushtaq v. Mukasey","cite":"306 F. App’x 882","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/306/882/","by":{"0":"40"}},{"t":"case","label":"Nasrallah v. Barr","cite":"140 S. Ct. 1683","y":2020,"id":"2019/18-1432","sc":1,"by":{"0":"8, 39","1":"39","2":"18"},"q":[{"src":"argument","who":"Mr. Fleming","text":"This Court said this in -- in Nasrallah. It's a factual issue that is reviewable on appeal deferentially. We don't dispute that. But, you know, in this case, for example, we think that the credibility determination against Mr."},{"src":"argument","who":"Mr. Raynor","text":"So this was -- this was at issue in Nasrallah, for example. The determination there simply didn't fall within the review bar in the first place, so whether it fell within subparagraph (D) was irrelevant."},{"src":"argument","who":"Mr. Fleming","text":"In this Court's decision in Nasrallah, on page 1693, the Court says those factual issues, regarding a Convention Against Torture order, may range from the non-citizen's past experiences in the designated country of removal, to the non-citizen's credibility, to the political or other current conditions of the country."}]},{"t":"case","label":"National Ass’n of Manufacturers v. Department of Defense","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"by":{"0":"19, 37, 38","2":"7"},"q":[{"src":"brief","b":0,"text":"necessarily depends on the statutory context.","cite":"138 S. Ct. 617, 629"},{"src":"brief","b":2,"text":"necessarily depends on the statutory context.","cite":"138 S. Ct. 617, 629"}]},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"by":{"0":"1, 7"},"q":[{"src":"brief","b":0,"text":"For more than a century, Congress has afforded the Attorney General (or other executive officials) discretion to allow otherwise removable aliens to remain in the country.","cite":"141 S. Ct. 1474, 1478"}]},{"t":"case","label":"Ortiz-Cornejo v. Gonzales","cite":"400 F.3d 610","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/400/610/","by":{"0":"41","1":"31"}},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"by":{"0":"6"}},{"t":"case","label":"Portillo Flores v. Garland","cite":"3 F.4th 615","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/3/615/","by":{"0":"29"}},{"t":"case","label":"Page(s) Santana-Albarran v. Ashcroft","cite":"393 F.3d 699","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/393/699/","by":{"0":"41","1":"31"}},{"t":"case","label":"Sepulveda v. Gonzales","cite":"407 F.3d 59","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/407/59/","by":{"0":"41","1":"31"}},{"t":"case","label":"Singh v. Rosen","cite":"984 F.3d 1142","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/984/1142/","by":{"0":"34"}},{"t":"case","label":"Subhan v. Ashcroft","cite":"383 F.3d 591","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/383/591/","by":{"0":"41"}},{"t":"case","label":"Trejo v. Garland","cite":"3 F.4th 760","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/3/760/","by":{"0":"6, 21, 31, 34, 40","1":"27"},"q":[{"src":"brief","b":0,"text":"who among the eligible persons should be granted discretionary relief.","cite":"3 F.4th 760, 767"},{"src":"argument","who":"Ms. Meehan","text":"And if you look at the Trejo decision from the Fifth Circuit that's cited, I think, in all the briefs here, that's the existing circuit split, it's the best illustration of the unworkability of the government's approach, where some circuits have said some eligibility determination is too discretionary; other circuits have said no, it's not discretionary."}]},{"t":"case","label":"United States v. Denedo","cite":"556 U.S. 904","y":2009,"id":"2008/08-267","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"‘redress or benefit’ provided by a court.","cite":"556 U.S. 904, 909-910"}]},{"t":"case","label":"Vendo Co v. Lektro-Vend Corp.","cite":"434 U.S. 425","y":1978,"id":"1977/76-156","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"the judgment is typically a routine order directing that the decision of this Court be carried into effect.","cite":"434 U.S. 425, 428"}]},{"t":"case","label":"Yepes-Prado v. INS","cite":"10 F.3d 1363","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/10/1363/","by":{"0":"9","2":"11"}},{"t":"case","label":"Young v. United Parcel Service, Inc.","cite":"135 S. Ct. 1338","y":2015,"id":"2014/12-1226","sc":1,"by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"‘a statute ought, upon the whole, to be so construed that … no clause’ is rendered ‘superfluous, void, or insignificant.’","cite":"135 S. Ct. 1338, 1352"}]},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)(7)"],"stext":{"head":"§1103. Powers and duties of the Secretary, the Under Secretary, and the Attorney General","paras":[[0,"(a) Secretary of Homeland Security"],[0,"(1) The Secretary of Homeland Security shall be charged with the administration and enforcement of this chapter and all other laws relating to the immigration and naturalization of aliens, except insofar as this chapter or such laws relate to the powers, functions, and duties conferred upon the President, Attorney General, the Secretary of State, the officers of the Department of State, or diplomatic or consular officers: Provided, however, That determination and ruling by the Attorney General with respect to all questions of law shall be controlling."],[0,"(2) He shall have control, direction, and supervision of all employees and of all the files and records of the Service."],[0,"(3) He shall establish such regulations; prescribe such forms of bond, reports, entries, and other papers; issue such instructions; and perform such other acts as he deems necessary for carrying out his authority under the provisions of this chapter."],[0,"(4) He may require or authorize any employee of the Service or the Department of Justice to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon any other employee of the Service."],[0,"(5) He shall have the power and duty to control and guard the boundaries and borders of the United States against the illegal entry of aliens and shall, in his discretion, appoint for that purpose such number of employees of the Service as to him shall appear necessary and proper."],[0,"(6) He is authorized to confer or impose upon any employee of the United States, with the consent of the head of the Department or other independent establishment under whose jurisdiction the employee is serving, any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(7) He may, with the concurrence of the Secretary of State, establish offices of the Service in foreign countries; and, after consultation with the Secretary of State, he may, whenever in his judgment such action may be necessary to accomplish the purposes of this chapter, detail employees of the Service for duty in foreign countries."],[0,"(8) After consultation with the Secretary of State, the Attorney General may authorize officers of a foreign country to be stationed at preclearance facilities in the United States for the purpose of ensuring that persons traveling from or through the United States to that foreign country comply with that country's immigration and related laws."],[0,"(9) Those officers may exercise such authority and perform such duties as United States immigration officers are authorized to exercise and perform in that foreign country under reciprocal agreement, and they shall enjoy such reasonable privileges and immunities necessary for the performance of their duties as the government of their country extends to United States immigration officers."],[0,"(10) In the event the Attorney General determines that an actual or imminent mass influx of aliens arriving off the coast of the United States, or near a land border, presents urgent circumstances requiring an immediate Federal response, the Attorney General may authorize any State or local law enforcement officer, with the consent of the head of the department, agency, or establishment under whose jurisdiction the individual is serving, to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(11) The Attorney General, in support of persons in administrative detention in non-Federal institutions, is authorized—"],[1,"(A) to make payments from funds appropriated for the administration and enforcement of the laws relating to immigration, naturalization, and alien registration for necessary clothing, medical care, necessary guard hire, and the housing, care, and security of persons detained by the Service pursuant to Federal law under an agreement with a State or political subdivision of a State; and"],[1,"(B) to enter into a cooperative agreement with any State, territory, or political subdivision thereof, for the necessary construction, physical renovation, acquisition of equipment, supplies or materials required to establish acceptable conditions of confinement and detention services in any State or unit of local government which agrees to provide guaranteed bed space for persons detained by the Service."],[0,"(b) Land acquisition authority"],[0,"(1) The Attorney General may contract for or buy any interest in land, including temporary use rights, adjacent to or in the vicinity of an international land border when the Attorney General deems the land essential to control and guard the boundaries and borders of the United States against any violation of this chapter."],[0,"(2) The Attorney General may contract for or buy any interest in land identified pursuant to paragraph (1) as soon as the lawful owner of that interest fixes a price for it and the Attorney General considers that price to be reasonable."],[0,"(3) When the Attorney General and the lawful owner of an interest identified pursuant to paragraph (1) are unable to agree upon a reasonable price, the Attorney General may commence condemnation proceedings pursuant to section 3113 of title 40."],[0,"(4) The Attorney General may accept for the United States a gift of any interest in land identified pursuant to paragraph (1)."],[0,"(c) Commissioner; appointment"],[0,"The Commissioner shall be a citizen of the United States and shall be appointed by the President, by and with the advice and consent of the Senate. He shall be charged with any and all responsibilities and authority in the administration of the Service and of this chapter which are conferred upon the Attorney General as may be delegated to him by the Attorney General or which may be prescribed by the Attorney General. The Commissioner may enter into cooperative agreements with State and local law enforcement agencies for the purpose of assisting in the enforcement of the immigration laws."],[0,"(d) Statistical information system"],[0,"(1) The Commissioner, in consultation with interested academicians, government agencies, and other parties, shall provide for a system for collection and dissemination, to Congress and the public, of information (not in individually identifiable form) useful in evaluating the social, economic, environmental, and demographic impact of immigration laws."],[0,"(2) Such information shall include information on the alien population in the United States, on the rates of naturalization and emigration of resident aliens, on aliens who have been admitted, paroled, or granted asylum, on nonimmigrants in the United States (by occupation, basis for admission, and duration of stay), on aliens who have not been admitted or have been removed from the United States, on the number of applications filed and granted for cancellation of removal, and on the number of aliens estimated to be present unlawfully in the United States in each fiscal year."],[0,"(3) Such system shall provide for the collection and dissemination of such information not less often than annually."],[0,"(e) Annual report"],[0,"(1) The Commissioner shall submit to Congress annually a report which contains a summary of the information collected under subsection (d) and an analysis of trends in immigration and naturalization."],[0,"(2) Each annual report shall include information on the number, and rate of denial administratively, of applications for naturalization, for each district office of the Service and by national origin group."],[0,"(f) Minimum number of agents in States"],[0,"The Attorney General shall allocate to each State not fewer than 10 full-time active duty agents of the Immigration and Naturalization Service to carry out the functions of the Service, in order to ensure the effective enforcement of this chapter."],[0,"(g) Attorney General"],[0,"(1) In general"],[1,"The Attorney General shall have such authorities and functions under this chapter and all other laws relating to the immigration and naturalization of aliens as were exercised by the Executive Office for Immigration Review, or by the Attorney General with respect to the Executive Office for Immigration Review, on the day before the effective date of the Immigration Reform, Accountability and Security Enhancement Act of 2002."],[0,"(2) Powers"],[1,"The Attorney General shall establish such regulations, prescribe such forms of bond, reports, entries, and other papers, issue such instructions, review such administrative determinations in immigration proceedings, delegate such authority, and perform such other acts as the Attorney General determines to be necessary for carrying out this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1103?type=usc&year=mostrecent&link-type=html"},"by":{"0":"27","1":"20"},"q":[{"src":"brief","b":0,"text":"whenever in his judgment such action may be necessary,","cite":"8 U.S.C. § 1103(a)(7)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"5"}},{"t":"law","label":"Illegal Immigration Reform and Immigrant Responsibility Act, Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"9, 30","1":"14"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/4978","by":{"0":"27"}},{"t":"reg","label":"8 C.F.R. § 240.25","url":"https://www.ecfr.gov/current/title-8/section-240.25","by":{"0":"42"}},{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"by":{"1":"33"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"1":"33, 34"}},{"t":"case","label":"Artis v. District of Columbia","cite":"138 S. Ct. 594","y":2018,"id":"2017/16-460","sc":1,"by":{"1":"16"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"by":{"1":"21, 27"},"q":[{"src":"brief","b":1,"text":"presum[e] that a given term is used to mean the same thing throughout a statute,","cite":"513 U.S. 115, 118"}]},{"t":"case","label":"Castro v. Holder","cite":"727 F.3d 125","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/727/125/","by":{"1":"42"}},{"t":"case","label":"Cevilla v. Gonzales","cite":"446 F.3d 658","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/446/658/","by":{"1":"35"}},{"t":"case","label":"Dave v. Ashcroft","cite":"363 F.3d 649","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/363/649/","by":{"1":"31"}},{"t":"case","label":"De Brown v. Department of Justice","cite":"18 F.3d 774","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/18/774/","by":{"1":"27"},"q":[{"src":"argument","who":"Mr. Fleming","text":"Chief Justice, and may it please the Court: As the government agrees, section 1252(a)(2)(B)(i) does not bar review of the agency's threshold determination that Mr."},{"src":"argument","who":"Mr. Fleming","text":"So, Justice Thomas, the review in an immigration case is of a final order of removal. And as this Court said in Chadha, the final order of removal subsumes everything that goes before."},{"src":"argument","who":"Mr. Fleming","text":"So there -- there are two differences, Justice Thomas. One is the word \"judgment\" in administrative law and immigration law is used in a narrow way to mean a discretionary determination or discretionary decision."}]},{"t":"case","label":"(III) Cases—Continued: De la Vega v. Gonzales","cite":"436 F.3d 141","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/436/141/","by":{"1":"35"}},{"t":"case","label":"Department of Commerce v. United States House of Representatives","cite":"525 U.S. 316","y":1999,"id":"1998/98-404","sc":1,"by":{"1":"29"}},{"t":"case","label":"Facebook, Inc. v. Duguid","cite":"141 S. Ct. 1163","y":2021,"id":"2020/18-956","sc":1,"by":{"1":"37"}},{"t":"case","label":"Garcia-Melendez v. Ashcroft","cite":"351 F.3d 657","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/351/657/","by":{"1":"31"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"when a Government official’s determination of a fact or circumstance * * * is dispositive of a court controversy, federal courts generally do not hold the determination unreviewable,","cite":"515 U.S. 417, 424"}]},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"by":{"1":"19"}},{"t":"case","label":"Hashish v. Gonzales","cite":"442 F.3d 572","y":2006,"url":"https://www.courtlistener.com/c/F.3d/442/572/","by":{"1":"35"}},{"t":"case","label":"Hughes Aircraft Co. v. Jacobson","cite":"525 U.S. 432","y":1999,"id":"1998/97-1287","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"begins with ‘the language of the statute.’","cite":"525 U.S. 432, 438"}]},{"t":"case","label":"Iddir v. Immigration & Naturalization Serv.","cite":"301 F.3d 492","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/301/492/","by":{"1":"31, 32"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"by":{"1":"39","2":"18"},"q":[{"src":"brief","b":2,"text":"‘not bound to follow [its] dicta in a prior case in which the point now at issue was not fully debated.’","cite":"568 U.S. 519, 548"}]},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"in a legal context generally ha[ve] a broadening effect, ensuring that the scope of a provision covers not only its subject but also matters relating to that subject.","cite":"138 S. Ct. 1752, 1760"}]},{"t":"case","label":"Melendez v. McAleenan","cite":"928 F.3d 425","y":2019,"url":"https://www.courtlistener.com/c/F.3d/928/425/","by":{"1":"35"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"by":{"1":"33"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"Although section headings cannot limit the plain meaning of a statutory text, ‘they supply cues’ as to what Congress intended.","cite":"138 S. Ct. 883, 893"}]},{"t":"case","label":"Molina-Estrada v. Immigration & Naturalization Serv.","cite":"293 F.3d 1089","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/293/1089/","by":{"1":"31"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"by":{"1":"24"}},{"t":"case","label":"Pena v. Lynch","cite":"815 F.3d 452","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/815/452/","by":{"1":"25"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"by":{"1":"22, 28, 40","2":"14"},"q":[{"src":"brief","b":1,"text":"protecting the Executive’s discretion from the courts.","cite":"525 U.S. 471, 486"},{"src":"argument","who":"Ms. Meehan","text":"It bars immediate review of questions of law in the same way this Court in Reno versus AADC and Reno versus Catholic Social Services barred immediate review, but there will be some --"},{"src":"argument","who":"Ms. Meehan","text":"And I think the Court's decision in Reno versus AADC is exactly on point here, where there were immediate constitutional claims, First Amendment claims and Fifth Amendment claims, about the government's selective prosecution, and the Court here held that those claims would have to wait."}]},{"t":"case","label":"Reyes-Sanchez v. Holder","cite":"646 F.3d 493","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/646/493/","by":{"1":"35"}},{"t":"case","label":"Rimini St., Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"by":{"1":"18"}},{"t":"case","label":"Roland v. United States Citizenship & Immigration Servs.","cite":"850 F.3d 625","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/625/","by":{"1":"35"}},{"t":"case","label":"Romero-Torres v. Ashcroft","cite":"327 F.3d 887","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/327/887/","by":{"1":"42"},"q":[{"src":"brief","b":1,"text":"an inquiry is discretionary where it is a ‘subjective question’ that depends on the value judgment ‘of the person or entity examining the issue.’","cite":"327 F.3d 887, 891"}]},{"t":"case","label":"Sabido Valdivia v. Gonzales","cite":"423 F.3d 1144","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/423/1144/","by":{"1":"35, 42"}},{"t":"case","label":"Sanchez v. Mayorkas","cite":"141 S. Ct. 1809","y":2021,"id":"2020/20-315","sc":1,"by":{"1":"37"}},{"t":"case","label":"Silva-Palacios v. Attorney Gen.","cite":"423 F.2d 725","y":1970,"url":"https://www.courtlistener.com/c/F.2d/423/725/","by":{"1":"25"}},{"t":"case","label":"Sturgeon v. Frost","cite":"577 U.S. 424","y":2016,"id":"2015/14-1209","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"[i]t is a fundamental canon of statutory construction that the words of a statute must be read in their context and with a view to their place in the overall statutory scheme,","cite":"577 U.S. 424, 438"}]},{"t":"case","label":"Succar v. Ashcroft","cite":"394 F.3d 8","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/394/8/","by":{"1":"31"}},{"t":"case","label":"Taylor v. United States","cite":"136 S. Ct. 2074","y":2016,"id":"2015/14-6166","sc":1,"by":{"1":"24"}},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affairs v. Inclusive Cmtys. Project","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"convincing support for the conclusion that Congress accepted and ratified","cite":"576 U.S. at 536"}]},{"t":"case","label":"United Sav. Ass’n v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"Statutory construction * * * is a holistic endeavor,","cite":"484 U.S. 365, 371"}]},{"t":"case","label":"United States v. Standard Brewery, Inc.","cite":"251 U.S. 210","y":1920,"id":"scdb/1919-173","sc":1,"by":{"1":"23"}},{"t":"case","label":"United States v. United Verde Copper Co.","cite":"196 U.S. 207","y":1905,"id":"scdb/1904-162","sc":1,"by":{"1":"23"}},{"t":"const","label":"Article I, Section 9, Clause 2","clauses":[["habeas","Suspension Clause (Habeas Corpus)"]],"text":"The Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","by":{"1":"14"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)","(a)(48)(A)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"by":{"1":"2, 3, 19","2":"5"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(a)(6)(A)(i)","(a)(6)(C)(ii)","(a)(6)(C)(ii)(I)","(a)(6)(C)(ii)(II)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"by":{"1":"25, 3, 7, 8, 4, 15, 4"},"q":[{"src":"brief","b":1,"text":"ineligible to be admitted to the United States,","cite":"8 U.S.C. 1182(a)"}]},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(e)"],"by":{"1":"20, 21"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(a)(1)","(c)(4)(A)(i)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"by":{"1":"25, 3"},"q":[{"src":"brief","b":1,"text":"merits a favorable exercise of discretion.","cite":"8 U.S.C. 1229a(c)(4)(A)(i)"},{"src":"argument","who":"Mr. Raynor","text":"If you look at Section 1229a, it specifies the different criteria that a court should consider in assessing credibility, and they're all factual considerations, although I -- I acknowledge that it's a slightly more complicated one than the question did he check the box or not."}]},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(a)(2)","(a)(2)(A)","(a)(2)(A)(i)","(a)(2)(B)","(a)(2)(B)(i)","(a)(2)(B)(ii)","(a)(2)(C)","(a)(2)(D)","(a)(5)","(b)(1)","(b)(4)(B)","(b)(4)(D)","(b)(9)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"1":"25, 25, 25, 25, passim, passim, passim, 13, 22, 23, 28, 29, 13, 22, 23, 28, 29, 4, 35, 4, 35, 4, 35, 28, 28, 21, 4, 26"},"q":[{"src":"brief","b":1,"text":"available only in judicial review of a final order","cite":"8 U.S.C. 1252(b)(9)"},{"src":"brief","b":1,"text":"any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in [his] discretion.","cite":"8 U.S.C. 1252(a)(2)(B)(ii)"},{"src":"argument","who":"Ms. Meehan","text":"And -- and to Petitioners' argument that -- that -- that \"regarding\" is -- is -- is a term of art or is a way of thinking about targeting those second-step decisions, I think that's just wrong, and -- and Section 1252 shows us why."}]},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(e)(3)","(i)","(i)(1)(B)(ii)","(i)(2)","(i)(2)(A)"],"stext":{"head":"§1255. Adjustment of status of nonimmigrant to that of person admitted for permanent residence","paras":[[0,"(a) Status as person admitted for permanent residence on application and eligibility for immigrant visa"],[0,"The status of an alien who was inspected and admitted or paroled into the United States or the status of any other alien having an approved petition for classification as a VAWA self-petitioner may be adjusted by the Attorney General, in his discretion and under such regulations as he may prescribe, to that of an alien lawfully admitted for permanent residence if (1) the alien makes an application for such adjustment, (2) the alien is eligible to receive an immigrant visa and is admissible to the United States for permanent residence, and (3) an immigrant visa is immediately available to him at the time his application is filed."],[0,"(b) Record of lawful admission for permanent residence; reduction of preference visas"],[0,"Upon the approval of an application for adjustment made under subsection (a), the Attorney General shall record the alien's lawful admission for permanent residence as of the date the order of the Attorney General approving the application for the adjustment of status is made, and the Secretary of State shall reduce by one the number of the preference visas authorized to be issued under sections 1152 and 1153 of this title within the class to which the alien is chargeable for the fiscal year then current."],[0,"(c) Alien crewmen, aliens continuing or accepting unauthorized employment, and aliens admitted in transit without visa"],[0,"Other than an alien having an approved petition for classification as a VAWA self-petitioner, subsection (a) shall not be applicable to (1) an alien crewman; (2) subject to subsection (k), an alien (other than an immediate relative as defined in section 1151(b) of this title or a special immigrant described in section 1101(a)(27)(H), (I), (J), or (K) of this title) who hereafter continues in or accepts unauthorized employment prior to filing an application for adjustment of status or who is in unlawful immigration status on the date of filing the application for adjustment of status or who has failed (other than through no fault of his own or for technical reasons) to maintain continuously a lawful status since entry into the United States; (3) any alien admitted in transit without visa under section 1182(d)(4)(C) of this title; (4) an alien (other than an immediate relative as defined in section 1151(b) of this title) who was admitted as a nonimmigrant visitor without a visa under section 1182(l) of this title or section 1187 of this title; (5) an alien who was admitted as a nonimmigrant described in section 1101(a)(15)(S) of this title,1 (6) an alien who is deportable under section 1227(a)(4)(B) of this title; (7) any alien who seeks adjustment of status to that of an immigrant under section 1153(b) of this title and is not in a lawful nonimmigrant status; or (8) any alien who was employed while the alien was an unauthorized alien, as defined in section 1324a(h)(3) of this title, or who has otherwise violated the terms of a nonimmigrant visa."],[0,"(d) Alien admitted for permanent residence on conditional basis; fiancee or fiance of citizen"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186a of this title. The Attorney General may not adjust, under subsection (a), the status of a nonimmigrant alien described in section 1101(a)(15)(K) of this title except to that of an alien lawfully admitted to the United States on a conditional basis under section 1186a of this title as a result of the marriage of the nonimmigrant (or, in the case of a minor child, the parent) to the citizen who filed the petition to accord that alien's nonimmigrant status under section 1101(a)(15)(K) of this title."],[0,"(e) Restriction on adjustment of status based on marriages entered while in admissibility or deportation proceedings; bona fide marriage exception"],[0,"(1) Except as provided in paragraph (3), an alien who is seeking to receive an immigrant visa on the basis of a marriage which was entered into during the period described in paragraph (2) may not have the alien's status adjusted under subsection (a)."],[0,"(2) The period described in this paragraph is the period during which administrative or judicial proceedings are pending regarding the alien's right to be admitted or remain in the United States."],[0,"(3) Paragraph (1) and section 1154(g) of this title shall not apply with respect to a marriage if the alien establishes by clear and convincing evidence to the satisfaction of the Attorney General that the marriage was entered into in good faith and in accordance with the laws of the place where the marriage took place and the marriage was not entered into for the purpose of procuring the alien's admission as an immigrant and no fee or other consideration was given (other than a fee or other consideration to an attorney for assistance in preparation of a lawful petition) for the filing of a petition under section 1154(a) of this title or subsection (d) or (p) 2 of section 1184 of this title with respect to the alien spouse or alien son or daughter. In accordance with regulations, there shall be only one level of administrative appellate review for each alien under the previous sentence."],[0,"(f) Limitation on adjustment of status"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186b of this title."],[0,"(g) Special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(K) of this title, such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States."],[0,"(h) Application with respect to special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(J) of this title—"],[1,"(1) such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States; and"],[1,"(2) in determining the alien's admissibility as an immigrant—"],[2,"(A) paragraphs (4), (5)(A), (6)(A), (6)(C), (6)(D), (7)(A), and (9)(B) of section 1182(a) of this title shall not apply; and"],[2,"(B) the Attorney General may waive other paragraphs of section 1182(a) of this title (other than paragraphs (2)(A), (2)(B), (2)(C) (except for so much of such paragraph as related to a single offense of simple possession of 30 grams or less of marijuana), (3)(A), (3)(B), (3)(C), and (3)(E)) in the case of individual aliens for humanitarian purposes, family unity, or when it is otherwise in the public interest."],[0,"The relationship between an alien and the alien's natural parents or prior adoptive parents shall not be considered a factor in making a waiver under paragraph (2)(B). Nothing in this subsection or section 1101(a)(27)(J) of this title shall be construed as authorizing an alien to apply for admission or be admitted to the United States in order to obtain special immigrant status described in such section."],[0,"(i) Adjustment in status of certain aliens physically present in United States"],[0,"(1) Notwithstanding the provisions of subsections (a) and (c) of this section, an alien physically present in the United States—"],[1,"(A) who—"],[2,"(i) entered the United States without inspection; or"],[2,"(ii) is within one of the classes enumerated in subsection (c) of this section;"],[1,"(B) who is the beneficiary (including a spouse or child of the principal alien, if eligible to receive a visa under section 1153(d) of this title) of—"],[2,"(i) a petition for classification under section 1154 of this title that was filed with the Attorney General on or before April 30, 2001; or"],[2,"(ii) an application for a labor certification under section 1182(a)(5)(A) of this title that was filed pursuant to the regulations of the Secretary of Labor on or before such date; and"],[1,"(C) who, in the case of a beneficiary of a petition for classification, or an application for labor certification, described in subparagraph (B) that was filed after January 14, 1998, is physically present in the United States on December 21, 2000;"],[0,"may apply to the Attorney General for the adjustment of his or her status to that of an alien lawfully admitted for permanent residence. The Attorney General may accept such application only if the alien remits with such application a sum equalling $1,000 as of the date of receipt of the application, but such sum shall not be required from a child under the age of seventeen, or an alien who is the spouse or unmarried child of an individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986 at any date, who—"],[1,"(i) as of May 5, 1988, was the unmarried child or spouse of the individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986;"],[1,"(ii) entered the United States before May 5, 1988, resided in the United States on May 5, 1988, and is not a lawful permanent resident; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1255?type=usc&year=mostrecent&link-type=html"},"by":{"1":"passim, 42, 21, 21, 21, 21"},"q":[{"src":"brief","b":1,"text":"is admissible to the United States for permanent residence.","cite":"8 U.S.C. 1255(i)(2)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1537","url":"https://www.law.cornell.edu/uscode/text/8/1537","subs":["(b)(2)(A)"],"by":{"1":"21"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","by":{"1":"32"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"1":"14"}},{"t":"case","label":"Gov’t Reh’g Br., Montero-Martinez v. Ashcroft","cite":"2001 WL 37115663","y":2001,"court":"9th Cir. Nov. 30","by":{"1":"9"}},{"t":"case","label":"Abuelhawa v. United States","cite":"556 U.S. 816","y":2009,"id":"2008/08-192","sc":1,"by":{"2":"10"}},{"t":"case","label":"Akinyemi v. INS","cite":"969 F.2d 285","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/969/285/","by":{"2":"11"}},{"t":"case","label":"Anderson v. City of Bessemer","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"by":{"2":"9"}},{"t":"case","label":"Biestek v. Berryhill","cite":"139 S. Ct. 1148","y":2019,"id":"2018/17-1184","sc":1,"by":{"2":"21"}},{"t":"case","label":"California Division of Labor Standards Enforcement v. Dillingham Construction, N.A., Inc.","cite":"519 U.S. 316","y":1997,"id":"1996/95-789","sc":1,"by":{"2":"12"}},{"t":"case","label":"Consumer Product Safety Commission v. GTE Sylvania, Inc.","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"by":{"2":"20"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"by":{"2":"10"}},{"t":"case","label":"Department of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"by":{"2":"9"}},{"t":"case","label":"Espinoza v. INS","cite":"991 F.2d 1294","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/991/1294/","by":{"2":"11"}},{"t":"case","label":"Etemadi v. Garland","cite":"12 F.4th 1013","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/12/1013/","by":{"2":"21"}},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"by":{"2":"8, 9"}},{"t":"case","label":"Page(s) Garcia-Torres v. Holder","cite":"660 F.3d 333","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/660/333/","by":{"2":"21"}},{"t":"case","label":"Georgiu v. INS","cite":"90 F.3d 374","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/90/374/","by":{"2":"11"}},{"t":"case","label":"Guillen-Garcia v. INS","cite":"999 F.2d 199","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/999/199/","by":{"2":"11"}},{"t":"case","label":"INS v. Elias-Zacarias","cite":"502 U.S. 478","y":1992,"id":"1991/90-1342","sc":1,"by":{"2":"21"}},{"t":"case","label":"Kahn v. INS","cite":"36 F.3d 1412","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/36/1412/","by":{"2":"11"}},{"t":"case","label":"Limani v. Mukasey","cite":"538 F.3d 25","y":2008,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/538/25/","by":{"2":"21"}},{"t":"case","label":"Sall v. Gonzales","cite":"437 F.3d 229","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/437/229/","by":{"2":"21"}},{"t":"case","label":"State Farm Fire & Casualty Co. v. United States ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"‘explicit language’ in one provision ‘cautions against inferring’ the same limitation in another provision.","cite":"137 S. Ct. 436, 442"}]},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"2":"7"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","by":{"2":"9"}}]};